class Solution {
public:
    long long maxSubarraySum(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> minP(k, LLONG_MAX);
        long long prefix = 0;
        long long ans = LLONG_MIN;
        for (int j = 0; j <= n; j++) {
            int r = j % k;
            if (minP[r] != LLONG_MAX) {
                long long cand = prefix - minP[r];
                if (cand > ans) ans = cand;
            }
            if (prefix < minP[r]) minP[r] = prefix;
            if (j < n) prefix += nums[j];
        }
        return ans;
    }
};
